style.css:
@-moz-document domain("roblox.com") {
body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background-image: url("https://i.imgur.com/rUs8RKw.jpeg"); /* Replace with your image URL */
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    z-index: -1;
    opacity: 0.6; /* Adjust for brightness */
    pointer-events: none;
  }

  /* Optional: slightly transparent containers for aesthetic blending */
  .container-main, .content, .navbar, .footer-container {
    background-color: rgba(255, 255, 255, 0.9) !important;
  }
}
